function image(id:string,still=reduced.matches){const a=assets[id],src=still||a?.file?.endsWith('.mp4')?a?.still||a?.poster||a?.file:a?.file||a?.still;const host=document.createElement('div');host.dataset.asset=id;if(!src){host.className='placeholder';host.style.cssText='height:100%;display:grid;place-items:center;background:#24212a;color:#8c7f6a;text-align:center';host.textContent=id;return host;}const im=document.createElement('img');im.src=`assets/${src}`;im.alt='';im.style.cssText='width:100%;height:100%;object-fit:cover';im.onerror=()=>{host.replaceChildren();host.textContent=id;host.style.background='#24212a';};host.append(im);return host;}
