function hud(before?:Record<string,unknown>){const separated=forward&&splitOutcome(state.outcome);$('hud').innerHTML=data.variables.filter(v=>v.visible).map(v=>{const n=state.dead&&v.id==='shen'?0:Number(state.values[v.id]),warn=n<=data.rules.warning.low||!data.rules.network&&v.id!=='身'&&n>=data.rules.warning.high,delta=before&&!separated?Number(n)-Number(before[v.id]):0,tag=forward?'button':'div';return `<${tag} class="bar ${warn?'warn':''}" data-bar="${esc(v.id)}" aria-label="${esc(v.label||v.id)} ${n}${warn?'，告急':''}"${forward?' type="button" aria-expanded="false"':''}><i style="height:${n}%"></i><img class="hud-icon" alt="" src="assets/art/icon/icon.${barIcons[v.id]||'guan'}.png"><span class="bar-letter">${esc(barLetters[v.id]||v.id)}</span>${forward?`<span class="bar-value">${n}</span>`:''}<span class="preview"></span>${Number.isFinite(delta)&&delta?`<span class="delta ${delta<0?'down':''}">${forward?(delta>0?'+':'')+delta:delta<0?'▼':'▲'}</span>`:''}</${tag}>`;}).join('')+`<div class="march"><span style="left:${Math.min(90,Number(state.values.金势))}%"><img src="assets/art/map/map.flag_jin.gif" alt="金军"></span><b><img src="assets/art/map/map.flag_song.gif" alt="东京"></b></div><button id="menu" aria-label="打开菜单">≡</button>`;
 $('menu').onclick=()=>openMenu();if(forward)for(const el of $('hud').querySelectorAll<HTMLElement>('[data-bar]'))el.onclick=()=>{const was=el.getAttribute('aria-expanded')==='true';$('hud').querySelector('.hud-help')?.remove();$('hud').querySelectorAll('[data-bar]').forEach(b=>b.setAttribute('aria-expanded','false'));if(was)return;el.setAttribute('aria-expanded','true');const id=el.dataset.bar!,v=data.variables.find(v=>v.id===id)!,note=document.createElement('div');note.className='hud-help';note.setAttribute('role','status');note.textContent=`${v.label||id} ${state.values[id]}/100（指数） · ${barHelp[id]||''}${lowValueExplanation(id)}`;const close=document.createElement('button');close.textContent='×';close.setAttribute('aria-label','关闭说明');close.onclick=()=>{note.remove();el.setAttribute('aria-expanded','false');};note.append(close);$('hud').append(note);};music.jin=Number(state.values.金势);stage.classList.toggle('sick',Number(state.values.shen??state.values.身)<20);}

