function persist(){if(!hasRun)return;remember(library,state,eng);storage.write(activePreview?'guanjia.library.v2.contract':'guanjia.library.v2',library);seen=[...new Set([...seen,...state.seen])];storage.write('guanjia.seen.v2',seen);storage.write(saveKey,{format:2,textLayout:TEXT_LAYOUT_VERSION,revision:contentRevision,preview:activePreview?.id,campaign:data.meta?.id||'guanjia',content:data.entry+':'+revision,state,snapshots:forward?[]:snapshots.slice(-100)});}
function stop(){controller.abort();clipActiveId='';clipPromise=undefined;controller=new AbortController();currentVideo?.pause();panelOpen=false;$('overlay').classList.add('hidden');$('choices').replaceChildren();$('incense').classList.add('hidden');stage.classList.remove('urgent');$('skip-opening').classList.add('hidden');}
function overlay(html:string,cls=''){$('overlay').className=cls;$('overlay').innerHTML=html;}
let endingSurface:{state:State;ending:string}|undefined,endingReadingSave:ReturnType<typeof setTimeout>|undefined;
function captureEndingReading(){const host=$('overlay');if(endingSurface?.state!==state||host.classList.contains('hidden')||!host.classList.contains('ending-screen'))return false;return rememberEndingReading(state,endingSurface.ending,host.scrollTop,Boolean(host.querySelector<HTMLDetailsElement>('.ending-review')?.open));}
